    out = [row[:] for row in grid]

    # Find contiguous bands of nonempty rows and columns; these define the tiles.
    def bands(indices):
        result = []
        start = None
        for i in indices + [None]:
            active = i is not None
            if active and start is None:
                start = i
            elif not active and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    row_bands = bands([r for r in range(h) if any(grid[r])])
    col_bands = bands([c for c in range(w) if any(grid[r][c] for r in range(h))])

    interior = set()
    counts = {}
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
